const FULL = new Map();
for (let i = 0; i < PAIRS.length; i += 2) FULL.set(PAIRS[i], PAIRS[i + 1] >>> 0);

/**
 * The full 32-bit MotionCommand for `cmd`. A command that already carries its
 * class bits (anything above 0xFFFF) is returned unchanged; a bare low-16 is
 * expanded; 0 and unknown ids are returned as-is.
 * @param {number} cmd
 * @returns {number}
 */
export function fullMotionCommand(cmd) {
  const c = cmd >>> 0;
  if (c === 0 || c > 0xffff) return c;
  return FULL.get(c) ?? c;
}

/** Number of known commands (for tests). */
export const FULL_MOTION_COMMAND_COUNT = FULL.size;
